// JVM Command-Line Flag Configurations for Production Environments

// 1. Enabling G1 GC with a target max pause time of 200ms
// java -XX:+UseG1GC -XX:MaxGCPauseMillis=200 -jar my-application.jar

// 2. Enabling ZGC for Ultra-Low Latency on a Large Heap
// java -XX:+UseZGC -Xms16g -Xmx16g -jar my-application.jar

public class GcDumpTrigger {
    public static void requestManualGcIfNeeded(long freeMemoryThreshold) {
        if (Runtime.getRuntime().freeMemory() < freeMemoryThreshold) {
            // Suggests garbage collection (caution: hint only, JVM decides)
            System.gc();
        }
    }
}
